def prepare_swap(path,size,identity,label):
    page=os.sysconf('SC_PAGE_SIZE');path=pathlib.Path(path)
    if type(size) is not int or not 1024*1024<=size<=16*1024*1024 or size%page or not isinstance(label,str) or not re.fullmatch(r'[A-Za-z0-9_.-]{1,15}',label):raise ValueError('bounded dense page-aligned swap artifact')
    try:parsed=uuid.UUID(identity)
    except (ValueError,TypeError,AttributeError) as error:raise ValueError('canonical UUID') from error
    if str(parsed)!=identity or parsed.int==0:raise ValueError('canonical nonzero UUID')
    fd=None;created=False
    try:
        fd=os.open(path,os.O_CREAT|os.O_EXCL|os.O_RDWR,0o600);created=True;os.fchmod(fd,0o600)
        os.posix_fallocate(fd,0,size);os.close(fd);fd=None
        subprocess.run(['mkswap','--pagesize',str(page),'--uuid',identity,'--label',label,str(path)],capture_output=True,text=True,check=True,timeout=4)
        return identity
    except BaseException:
        if fd is not None:os.close(fd)
        if created:path.unlink(missing_ok=True)
        raise
